/* v2.8.0 DNA, genomes and African ancestry: researched and checked 22 October 2026 */
const GN=[
 {k:"A",h:"Why Africa matters genetically",intro:"Modern humans emerged in Africa, and African populations hold more genetic variation than any other part of the world. Non-African populations carry a subset of that diversity.",points:[
  {h:"Africa holds the most human genetic diversity",text:"The 1000 Genomes Project (2015) found that people from African-ancestry populations carry the greatest number of variant sites. The H3Africa consortium describes Africa as containing more genetic diversity than any other continent.",figure:"2,504 genomes from 26 populations (1000 Genomes)",year:2015,disputed:false,note:"Diversity is a property of populations, not a ranking of people. More variation means existing reference data, built mostly from European-ancestry samples, misses more of what is in African genomes.",src:[SRCQ("A global reference for human genetic variation (Nature, 2015)","https://www.nature.com/articles/nature15393","Supports the DNA and genomes page","Individuals from African ancestry populations harbour the greatest numbers of variant sites"),SRCQ("Three Million African Genomes: A New Project for A New Generation (H3Africa)","https://h3africa.org/index.php/2021/02/26/three-million-african-genomes-a-new-project-for-a-new-generation/","Supports the DNA and genomes page","contains more genetic diversity than any other continent")]},
  {h:"Tishkoff et al. 2009: 121 African populations",text:"A major study of African genetic structure (Science, 2009) looked at 121 African populations, four African American populations and 60 non-African populations. It found 14 ancestral clusters in Africa that broadly match self-described ethnic, cultural and language groups. It estimated that, on average, African American ancestry was mostly from the Niger-Kordofanian cluster (about 71%, largely West and west-central African), with about 13% European and about 8% other African. Levels of mixed ancestry varied widely between individuals.",figure:"121 African populations; 14 ancestral clusters; ~71% Niger-Kordofanian, ~13% European, ~8% other African ancestry in African Americans (average)",year:2009,disputed:false,note:"The averages hide wide individual variation, which the paper itself notes. The suggested origin point near the Namibia–Angola coast comes from present-day diversity patterns and is a model estimate, not a fixed fact.",src:[SRCQ("The Genetic Structure and History of Africans and African Americans (Tishkoff et al., Science 2009)","https://faculty.washington.edu/wjs18/Pop_Structure/TishkoffAfrican.pdf","Supports the DNA and genomes page","We studied 121 African populations, four African American populations, and 60 non-African populations."),SRCQ("The Genetic Structure and History of Africans and African Americans (Tishkoff et al., Science 2009)","https://faculty.washington.edu/wjs18/Pop_Structure/TishkoffAfrican.pdf","Supports the DNA and genomes page","We identified 14 ancestral population clusters in Africa that correlate with self-described ethnicity"),SRCQ("The Genetic Structure and History of Africans and African Americans (Tishkoff et al., Science 2009)","https://faculty.washington.edu/wjs18/Pop_Structure/TishkoffAfrican.pdf","Supports the DNA and genomes page","The ancestry of African Americans is predominantly from Niger-Kordofanian (~71%), European (~13%)")]},
  {h:"The deepest population splits: southern African ancient genomes",text:"Schlebusch, Jakobsson and colleagues (Science, 2017) sequenced ancient southern Africans, including a Stone Age boy from Ballito Bay, South Africa. They estimated that modern human populations began to diverge 350,000 to 260,000 years ago. The oldest individuals were related to the descendants of southern Khoe-San groups.",figure:"Divergence 350,000–260,000 years ago",year:2017,disputed:true,note:"Divergence dates are model-based estimates and differ between studies and methods. Khoe-San populations are often described as carrying the deepest-branching lineages among living people; that wording is not confirmed by the sources cited.",src:[SRCQ("Modern humans emerged more than 300,000 years ago, new study suggests (Uppsala University, 28 Sep 2017)","https://www.uu.se/en/press/press-releases/2017/2017-09-28-modern-humans-emerged-more-than-300000-years-ago-new-study-suggests","Supports the DNA and genomes page","The authors estimate the divergence among modern humans to have occurred between 350,000 and 260,000 years ago."),SRCQ("Modern humans emerged more than 300,000 years ago, new study suggests (Uppsala University, 28 Sep 2017)","https://www.uu.se/en/press/press-releases/2017/2017-09-28-modern-humans-emerged-more-than-300000-years-ago-new-study-suggests","Supports the DNA and genomes page","The three oldest individuals dating to 2300-1800 years ago were genetically related to the descendants of the southern Khoe-San groups.")]},
  {h:"Ancient DNA from Africa",text:"Skoglund et al. (Cell, 2017) analysed 16 prehistoric Africans and showed that the spread of farmers from western Africa replaced local hunter-gatherer populations entirely in some regions. Lipson et al. (Nature, 2022) added ancient DNA from eastern and south-central Africa covering about 18,000 years, and found deep structure going back to interactions roughly 80,000 to 20,000 years ago.",figure:"16 prehistoric individuals (2017); 6 new individuals plus 28 previously published, spanning ~18,000 years (2022)",year:2022,disputed:false,note:"Africa's heat and humidity degrade DNA, so ancient African genomes are still few. Lipson et al. reported six new individuals and re-analysed or drew on data from 28 previously published ancient individuals.",src:[SRCQ("Reconstructing Prehistoric African Population Structure (Skoglund et al., Cell 2017)","https://www.eva.mpg.de/documents/Elsevier/Skoglund_Reconstructing_Cell_2017_2481658.pdf","Supports the DNA and genomes page","We assembled genome-wide data from 16 prehistoric Africans."),SRCQ("Reconstructing Prehistoric African Population Structure (Skoglund et al., Cell 2017)","https://www.eva.mpg.de/documents/Elsevier/Skoglund_Reconstructing_Cell_2017_2481658.pdf","Supports the DNA and genomes page","the spread of farmers from western Africa involved complete replacement of local hunter-gatherers in some regions"),SRCQ("Ancient DNA and deep population structure in sub-Saharan African foragers (Lipson et al., Nature 2022)","https://www.nature.com/articles/s41586-022-04430-9","Supports the DNA and genomes page","probably reflecting Pleistocene interactions around 80–20 thousand years ago")]}]},
 {k:"B",h:"Major projects and datasets",intro:"Since the mid-2000s a series of international, then African-led, projects have built reference data on African genomes. Large cohorts in the US and UK have also begun recruiting more people of African ancestry.",points:[
  {h:"HapMap and 1000 Genomes African-ancestry samples",text:"The International HapMap Project (from 2002) included 30 parent–child trios from the Yoruba in Ibadan, Nigeria. The 1000 Genomes Project (final paper 2015) included seven African-ancestry groups: Yoruba in Ibadan, Nigeria (YRI); Luhya in Webuye, Kenya (LWK); Gambian in Western Division, The Gambia (GWD); Mende in Sierra Leone (MSL); Esan in Nigeria (ESN); African Ancestry in Southwest US (ASW); and African Caribbean in Barbados (ACB).",figure:"7 African-ancestry groups of 26 in 1000 Genomes",year:2015,disputed:false,note:"A handful of groups cannot represent a continent of more than 2,000 ethnolinguistic groups. The Barbados (ACB) sample is one of the few Caribbean reference sets in widely used public data.",src:[SRCQ("About the International HapMap Project (NHGRI)","https://www.genome.gov/11511175/about-the-international-hapmap-project-fact-sheet","Supports the DNA and genomes page","from the Yoruba people in Ibadan, Nigeria (30 both-parent-and-adult-child trios)"),SRCQ("Population frequencies & genotypes (Ensembl)","https://grch37.ensembl.org/info/genome/variation/species/populations.html","Supports the DNA and genomes page","Gambian in Western Division, The Gambia"),SRCQ("Population frequencies & genotypes (Ensembl)","https://grch37.ensembl.org/info/genome/variation/species/populations.html","Supports the DNA and genomes page","African Caribbean in Barbados")]},
  {h:"African Genome Variation Project (2015)",text:"Led by the Wellcome Sanger Institute and African partners, the project (Nature, 2015) produced dense genotype data on 1,481 people and whole genomes for 320 people from 18 ethnolinguistic groups across sub-Saharan Africa.",figure:"1,481 genotyped; 320 whole genomes; 18 groups",year:2015,disputed:false,note:"",src:[SRCQ("The African Genome Variation Project shapes medical genetics in Africa (Gurdasani et al., Nature 2015)","https://www.nature.com/articles/nature13997","Supports the DNA and genomes page","dense genotypes from 1,481 individuals and whole-genome sequences from 320 individuals across sub-Saharan Africa")]},
  {h:"H3Africa (Human Heredity and Health in Africa)",text:"H3Africa grew out of a March 2009 meeting in Yaoundé, Cameroon, involving the African Society of Human Genetics, the NIH and the Wellcome Trust. It was announced in June 2010 and is supported by the NIH Common Fund and Wellcome, to fund African-led research on genetics, health and disease.",figure:"Announced June 2010",year:2010,disputed:false,note:"First funding awards followed the 2010 announcement; the year of the first awards is not confirmed by the sources cited. Nature News reported in 2018 that H3Africa was spending US$188 million over 10 years.",src:[SRCQ("Our History (H3Africa)","https://h3africa.org/index.php/about/","Supports the DNA and genomes page","Following this meeting the concept of H3Africa was developed and the initiative was announced in June 2010."),SRCQ("Our History (H3Africa)","https://h3africa.org/index.php/about/","Supports the DNA and genomes page","H3Africa is supported by the NIH Director's Common Fund as an initiative within its Global Health Program.")]},
  {h:"Choudhury et al. 2020: 426 high-depth African genomes",text:"An H3Africa study (Nature, October 2020) sequenced 426 people from 50 ethnolinguistic groups, including groups never sampled before, and found more than 3 million variants not previously described.",figure:"426 genomes; 50 groups; >3 million new variants (H3Africa press release: ~3.4 million; 13 countries)",year:2020,disputed:false,note:"The paper says 'more than 3 million'; the H3Africa press release says about 3.4 million and 13 countries.",src:[SRCQ("High-depth African genomes inform human migration and health (Nature, 2020)","https://www.nature.com/articles/s41586-020-2859-7","Supports the DNA and genomes page","We uncovered more than 3 million previously undescribed variants"),SRCQ("Genome Data from Africa Reveal Millions of New Variants (H3Africa)","https://h3africa.org/index.php/2020/11/10/genome-data-from-africa-reveal-millions-of-new-variants/","Supports the DNA and genomes page","50 distinct groups of people from 13 African countries")]},
  {h:"Uganda Genome Resource (2019)",text:"A study in Cell (2019) used genome-wide data from 6,400 people in rural Uganda, including whole genomes for 1,978. LSHTM reported ten new disease associations, nine of which are found only in Africans. One variant, present in about 22% of Africans, is associated with glycated haemoglobin (HbA1c), a marker used to diagnose diabetes, so diabetes may be misdiagnosed in some Africans.",figure:"6,400 people; ~2,000 whole genomes",year:2019,disputed:false,note:"Partners included LSHTM, the MRC/UVRI and LSHTM Uganda Research Unit and the Wellcome Sanger Institute. Details are from LSHTM's announcement and the Cell abstract.",src:[SRCQ("Largest ever genome study of Africans could lead to new disease treatments (LSHTM)","https://www.lshtm.ac.uk/newsevents/news/2019/largest-ever-genome-study-africans-could-lead-new-disease-treatments","Supports the DNA and genomes page","using genome wide data from 6,400 Africans, including whole genome sequencing of nearly 2,000 people"),SRCQ("Largest ever genome study of Africans could lead to new disease treatments (LSHTM)","https://www.lshtm.ac.uk/newsevents/news/2019/largest-ever-genome-study-africans-could-lead-new-disease-treatments","Supports the DNA and genomes page","The combined study identified new genes associated with several diseases.")]},
  {h:"Three Million African Genomes (3MAG) proposal",text:"In Nature (February 2021) Ambroise Wonkam (University of Cape Town) proposed sequencing three million African genomes over about a decade. He noted that fewer than 2% of human genomes analysed so far were from African people.",figure:"3 million genomes; ~10 years; ~$450 million a year",year:2021,disputed:false,note:"This is a proposal, not a funded or completed project.",src:[SRCQ("Sequence three million genomes across Africa (Wonkam, Nature 2021)","https://www.nature.com/articles/d41586-021-00313-7","Supports the DNA and genomes page","Less than 2% of human genomes analysed so far have been those of African people"),SRCQ("Sequence three million genomes across Africa (Wonkam, Nature 2021)","https://www.nature.com/articles/d41586-021-00313-7","Supports the DNA and genomes page","The development of 3MAG will probably take around a decade.")]},
  {h:"African BioGenome Project (not about human DNA)",text:"AfricaBP, started in 2021, sequences the genomes of African plants, animals and other species for conservation and sustainable use. It is affiliated with the Earth BioGenome Project. It is about biodiversity, not human genomes.",figure:"",year:2021,disputed:false,note:"Included because it was in the brief; it should not be presented as human-genome research.",src:[SRCQ("African BioGenome Project","https://africanbiogenome.org/","Supports the DNA and genomes page","generate, analyze and deploy genomics data for the improvement and sustainable use of biodiversity")]},
  {h:"54gene: rise and collapse",text:"54gene, a Nigerian genomics company founded in 2019 by Dr Abasi Ene-Obong, aimed to supply genetic data on Africans for drug research. It raised $45 million but began shutting down in July 2023. In 2025 a Federal High Court in Lagos granted an injunction blocking the sale of its assets, which reportedly included biodata on 100,000 Nigerians.",figure:"$45 million raised; biodata of 100,000 Nigerians",year:2023,disputed:true,note:"Sources are tech news reports, not official records. The reasons for its failure and the status of the samples are contested in court.",src:[SRCQ("TechCabal Daily: 54gene shuts down","https://techcabal.com/2023/09/28/techcabal-daily-54gene-shuts-down/","Supports the DNA and genomes page","By July 2023, however, the company started its shutdown process."),SRCQ("Nigerian court blocks sale of 54gene's assets, as founder claims investor wrongdoing (TechCabal)","https://techcabal.com/2025/08/01/54gene-collapse/","Supports the DNA and genomes page","Assets slated for sale included the biodata of 100,000 Nigerians priced at $3 million.")]},
  {h:"Large cohorts in the US",text:"The NIH All of Us programme released nearly a quarter of a million whole genomes in 2023. About 45% of the data came from people who self-identify with a racial or ethnic group historically under-represented in medical research. The US Million Veteran Program has more than one million participants.",figure:"~250,000 genomes, ~45% from under-represented groups (All of Us, 2023); >1 million (MVP)",year:2023,disputed:false,note:"The All of Us figure covers all under-represented groups, not only people of African ancestry. The MVP page gave no ancestry breakdown.",src:[SRCQ("All of Us genomic dataset is world's largest and most diverse dataset of its kind (NIH)","https://allofus.nih.gov/news-events/announcements/all-us-research-program-makes-nearly-250000-whole-genome-sequences-available-advance-precision-medicine","Supports the DNA and genomes page","About 45% of the data was donated by people who self-identify with a racial or ethnic group"),SRCQ("MVP Home (US Department of Veterans Affairs)","https://www.mvp.va.gov/pwa/","Supports the DNA and genomes page","Over one million Veterans are part of our program")]},
  {h:"UK cohorts and initiatives",text:"UK Biobank recruited 500,000 people aged 40 to 69 between 2006 and 2010. Our Future Health aims to bring together up to five million people and says it is building a community that reflects the UK population. Genomics England launched its Diverse Data initiative in September 2021 to tackle under-representation in genomic data.",figure:"UK Biobank 500,000; Our Future Health up to 5 million",year:2021,disputed:false,note:"The sources cited do not give the number or share of participants of Black African or Black Caribbean ancestry.",src:[SRCQ("About us (UK Biobank)","https://www.ukbiobank.ac.uk/learn-more-about-uk-biobank/about-us","Supports the DNA and genomes page","The UK Biobank study includes 500,000 participants, recruited between 2006 and 2010."),SRCQ("Our Future Health","https://ourfuturehealth.org.uk/","Supports the DNA and genomes page","We're building a diverse community of volunteers that truly reflects the UK's population."),SRCQ("Health Secretary participates in Diverse Data Initiative aimed at reducing health inequalities (Genomics England, 20 Sep 2021)","https://www.Genomicsengland.Co.Uk/news/health-secretary-sajid-javid-diverse-data-initiative","Supports the DNA and genomes page","Genomics England have launched the 'Diverse Data' initiative")]},
  {h:"Caribbean and Black British data",text:"Published, open reference data for Caribbean ancestry is thin. The main public sample is African Caribbean in Barbados (ACB) in 1000 Genomes. In the UK, the Sickle Cell Society reports sickle cell trait in about 1 in 4 West Africans and 1 in 10 Afro-Caribbeans, and notes it is also found in people with Mediterranean, Asian and Middle Eastern origins.",figure:"Trait: 1 in 4 West Africans; 1 in 10 Afro-Caribbeans",year:"",disputed:false,note:"The sources cited give no count of Black British participants in UK genomic cohorts.",src:[SRCQ("Population frequencies & genotypes (Ensembl)","https://grch37.ensembl.org/info/genome/variation/species/populations.html","Supports the DNA and genomes page","African Caribbean in Barbados"),SRCQ("About Sickle Cell and Trait (Sickle Cell Society)","https://www.sicklecellsociety.org/about-sickle-cell/","Supports the DNA and genomes page","Sickle cell trait is found in 1 in 4 West Africans and 1 in 10 Afro-Caribbeans.")]}]},
 {k:"C",h:"Under-representation",intro:"Most genetic research has studied people of European ancestry. This limits how well the findings work for everyone else, especially people of African ancestry.",points:[
  {h:"Popejoy and Fullerton 2016",text:"In Nature (October 2016), Popejoy and Fullerton reported that the share of genome-wide association study (GWAS) participants of European descent fell from 96% in 2009 to about 81% in 2016 (non-European participants rose to nearly 20%). Much of the rise came from studies in Asia of people of Asian ancestry. African-ancestry samples were about 3%.",figure:"European: 96% (2009) to 81% (2016); African: ~3%",year:2016,disputed:false,note:"The 96% and 'nearly 20%' figures are from the authors' manuscript. The 81% and 3% figures are from reports of the article's chart (MIT Technology Review, Bio-IT World). In the text, African, Hispanic/Latin American and Indigenous samples together are under 4%. Percentages depend on whether studies, participants or samples are counted.",src:[SRCQ("Solving the lack of diversity in genomic research (MIT Technology Review)","https://www.technologyreview.com/2016/10/25/156446/solving-the-lack-of-diversity-in-genomic-research/amp/","Supports the DNA and genomes page","81 percent of participants in these genome-wide association studies were of European descent."),SRCQ("Among the Multitude: A Look At The Complexity Of Diversity In Genetics (Bio-IT World)","https://bio-itworld.com/news/2016/10/13/among-the-multitude-a-look-at-the-complexity-of-diversity-in-genetics","Supports the DNA and genomes page","Only 3% of all the samples in the GWAS Catalog are African."),SRCQ("Genomics is failing on diversity (Popejoy & Fullerton, Nature 2016; author manuscript, PubMed Central)","https://pmc.ncbi.nlm.nih.gov/articles/PMC5089703/","Supports the DNA and genomes page","A 2009 analysis revealed that 96% of participants in genome-wide association studies (GWAS) were of European descent")]},
  {h:"Later estimates",text:"Genomics England states that about 80% of GWAS participants are of European ancestry and only 2% of African ancestry. Mills and Rahal (Communications Biology, 2019) found GWAS participants were still mostly of European ancestry (88% in 2017). A 2021 King's College London blog notes that more than 70% of GWAS participants are both of European descent and recruited in just three countries: the US, the UK and Iceland. Fatumo et al. (Nature Medicine, 2022) set out a roadmap to increase diversity.",figure:"~80% European; ~2% African (Genomics England); 88% European in 2017 (Mills and Rahal)",year:2022,disputed:true,note:"Estimates differ (roughly 1% to 3% African ancestry; 78% to 88% European) because of different counting methods and dates. The exact Fatumo 2022 figures are not confirmed by the sources cited.",src:[SRCQ("Diverse Data (Genomics England)","https://www.Genomicsengland.Co.Uk/Initiatives/Diverse-Data","Supports the DNA and genomes page","Only 2% of genome-wide association studies (GWAS) participants are of African genetic ancestry."),SRCQ("A roadmap to increase diversity in genomic studies (Fatumo et al., Nature Medicine 2022)","https://www.nature.com/articles/s41591-021-01672-4","Supports the DNA and genomes page","genetic and genomic studies are predominantly based on populations of European ancestry"),SRCQ("A scientometric review of genome-wide association studies (Mills & Rahal, Communications Biology 2019)","https://europepmc.org/article/MED/30623105","Supports the DNA and genomes page","still predominantly European Ancestry (88% in 2017)")]},
  {h:"Consequences: risk scores, uncertain variants, misdiagnosis",text:"Genomics England reports that some polygenic risk scores are about four times more accurate for people of European ancestry than for people of African ancestry. A 2026 Genomics England study of over 29,000 people with rare conditions found that, compared with people of European ancestry, people of East African ancestry had almost three times as many genetic changes flagged for review. Diagnosis rates were similar across ancestry groups once other factors were taken into account.",figure:"Risk scores ~4x more accurate for European ancestry; ~3x more flagged variants for East African ancestry",year:2026,disputed:false,note:"Flagged variants that cannot be classified are often called variants of uncertain significance. They create extra work and uncertainty for patients.",src:[SRCQ("Diverse Data (Genomics England)","https://www.Genomicsengland.Co.Uk/Initiatives/Diverse-Data","Supports the DNA and genomes page","Some polygenic risk scores are ~4x more accurate for people of European genetic ancestry than of African genetic ancestry."),SRCQ("More diverse genomic datasets could improve equity in rare conditions diagnoses (Genomics England)","https://www.genomicsengland.co.uk/news/more-diverse-genomic-datasets-could-improve-equity-in-rare-conditions-diagnoses","Supports the DNA and genomes page","people of East African ancestry had almost three times as many genetic changes flagged for scientists to review"),SRCQ("More diverse genomic datasets could improve equity in rare conditions diagnoses (Genomics England)","https://www.genomicsengland.co.uk/news/more-diverse-genomic-datasets-could-improve-equity-in-rare-conditions-diagnoses","Supports the DNA and genomes page","the likelihood of receiving a genetic diagnosis was similar across all ancestry groups once other factors were considered")]},
  {h:"Hypertrophic cardiomyopathy misclassification (Manrai et al. 2016)",text:"A Harvard study (New England Journal of Medicine, August 2016) found that genetic tests for hypertrophic cardiomyopathy, a heart condition, had misclassified variants as disease-causing in patients of African or unspecified ancestry. All the reported variants were later reclassified as benign. The variants were more common among Black Americans than white Americans, and including even small numbers of Black Americans in control groups would probably have prevented the errors.",figure:"",year:2016,disputed:false,note:"The study used a single testing laboratory's records. Its findings show the risk of reference data that lacks diversity, not a difference in disease between groups.",src:[SRCQ("Imprecise Diagnoses (Harvard Medical School DBMI, 16 Aug 2016)","https://dbmi.hms.harvard.edu/news/imprecise-diagnoses","Supports the DNA and genomes page","racially biased methodologies in early studies that defined certain common genetic variants as causes of HCM"),SRCQ("Genetic Misdiagnoses and the Potential for Health Disparities (Manrai et al., NEJM 2016; abstract)","https://europepmc.org/article/MED/27532831","Supports the DNA and genomes page","Subsequently, all reported variants were recategorized as benign.")]}]},
 {k:"D",h:"Health findings linked to ancestry",intro:"Some variants are more common in people with ancestry from particular regions, often because they once gave protection against local infections such as malaria. They are found in many populations, are not exclusive to any group, and do not define anyone's identity.",points:[
  {h:"Sickle cell and malaria",text:"Sickle cell disease is inherited and is more common in people with African, Caribbean, Mediterranean, south and southeast Asian, and Middle Eastern backgrounds. Carrying one copy (sickle cell trait) gives some protection against malaria. A CDC birth cohort study in western Kenya found the trait gave 60% protection against overall mortality, mostly between 2 and 16 months of age.",figure:"Trait 1 in 4 West Africans, 1 in 10 Afro-Caribbeans; 60% protection against overall mortality (Kenya study)",year:"",disputed:false,note:"UK figures for the number of people living with sickle cell disease are not confirmed by the sources cited.",src:[SRCQ("Sickle cell disease (NHS)","https://www.nhs.uk/conditions/sickle-cell-disease/","Supports the DNA and genomes page","Sickle cell disease is an inherited condition."),SRCQ("Protective Effect of Sickle Cell Trait Against Malaria-Associated Mortality And Morbidity (CDC)","https://www.cdc.gov/malaria/about/biology/sickle_cell.html","Supports the DNA and genomes page","the sickle cell trait provides 60% protection against overall mortality"),SRCQ("Sickle cell disease (MedlinePlus Genetics)","https://medlineplus.gov/genetics/condition/sickle-cell-disease/","Supports the DNA and genomes page","It is most common among people whose ancestors come from Africa")]},
  {h:"APOL1, kidney disease and sleeping sickness",text:"In 2010 NIH-funded researchers (Science) found that two APOL1 variants, common in people with African ancestry and absent from European chromosomes, raise the risk of kidney disease. Only the risk variants destroyed a parasite that causes African sleeping sickness in laboratory tests, so they are thought to protect against that infection.",figure:"",year:2010,disputed:false,note:"Most people who carry two risk variants do not develop kidney disease (NIDDK); other factors are involved.",src:[SRCQ("Association of trypanolytic ApoL1 variants with kidney disease in African Americans (Genovese et al., Science 2010; abstract)","https://europepmc.org/article/MED/20647424","Supports the DNA and genomes page","The two APOL1 variants are common in African chromosomes but absent from European chromosomes"),SRCQ("Story of Discovery: APOL1 Gene Variants (NIDDK, NIH)","https://www.niddk.nih.gov/news/archive/2017/story-variants-unraveling-genetic-basis-elevated-risk-kidney-disease-african-americans","Supports the DNA and genomes page","It should be noted that most people with two APOL1 variants do not develop kidney disease.")]},
  {h:"G6PD deficiency",text:"About 400 million people worldwide have G6PD deficiency. It is most frequent in parts of Africa, Asia, the Mediterranean and the Middle East, and may give partial protection against malaria.",figure:"~400 million people worldwide",year:"",disputed:false,note:"UK prevalence figures are not confirmed by the sources cited.",src:[SRCQ("Glucose-6-phosphate dehydrogenase deficiency (MedlinePlus Genetics)","https://medlineplus.gov/genetics/condition/glucose-6-phosphate-dehydrogenase-deficiency/","Supports the DNA and genomes page","An estimated 400 million people worldwide have glucose-6-phosphate dehydrogenase deficiency."),SRCQ("Glucose-6-phosphate dehydrogenase deficiency (MedlinePlus Genetics)","https://medlineplus.gov/genetics/condition/glucose-6-phosphate-dehydrogenase-deficiency/","Supports the DNA and genomes page","Researchers believe that people who have a G6PD variant may be partially protected against malaria.")]},
  {h:"Duffy-null and neutrophil counts (DANC)",text:"People with the Duffy-null blood type often have lower neutrophil (white blood cell) counts but no illness. Duffy-null is most common in people with African or Arabian Peninsula genetic ancestry but is not exclusive to them. In the US, about two in three people who identify as Black are expected to have it. Standard reference ranges can wrongly label them as neutropenic, causing unnecessary tests or delayed chemotherapy. The American Society of Hematology runs a project to redefine reference ranges by Duffy status, and has published Duffy-null-specific ranges.",figure:"~2 in 3 people identifying as Black in the US expected to be Duffy-null",year:"",disputed:false,note:"The older label 'benign ethnic neutropenia' is being replaced by 'Duffy-null associated neutrophil count', the term ASH uses. The date and origin of the renaming are not confirmed by the sources cited.",src:[SRCQ("Duffy-null Associated Neutrophil Count (DANC) (American Society of Hematology)","https://www.hematology.org/DANC","Supports the DNA and genomes page","Approximately two of three people identifying as Black in the U.S. are expected to have the Duffy-null phenotype."),SRCQ("Duffy-null Associated Neutrophil Count (DANC) (American Society of Hematology)","https://www.hematology.org/DANC","Supports the DNA and genomes page","often incorrectly labeled as having neutropenia"),SRCQ("Duffy-null Associated Neutrophil Count (DANC) (American Society of Hematology)","https://www.hematology.org/DANC","Supports the DNA and genomes page","redefining ANC reference ranges based on Duffy status")]},
  {h:"Pharmacogenomics and the BiDil caution",text:"Variants in genes such as CYP2C19, which processes at least 10% of commonly prescribed drugs, change how people respond to medicines such as clopidogrel. These variants occur in all populations at different frequencies, so testing the person works better than guessing from ancestry. BiDil, approved in the US in 2005 for heart failure in self-identified Black patients, was criticised as race-based medicine. FDA staff defended the approval on the basis of a trial in which self-identified Black patients had a 43% reduction in mortality.",figure:"CYP2C19 processes at least 10% of common drugs",year:2005,disputed:true,note:"The approval date is from secondary sources citing the FDA's June 2005 announcement. Population frequencies of CYP2D6 and CYP2C19 variants by ancestry are not confirmed by the sources cited.",src:[SRCQ("CYP2C19 gene (MedlinePlus Genetics)","https://medlineplus.gov/genetics/gene/cyp2c19/","Supports the DNA and genomes page","The CYP2C19 enzyme plays a role in the processing or metabolizing of at least 10 percent of commonly prescribed drugs."),SRCQ("BiDil for heart failure in black patients: The U.S. Food and Drug Administration perspective (Annals of Internal Medicine, 2007; abstract)","https://europepmc.org/article/MED/17200223","Supports the DNA and genomes page","a \"race-based\" approval could be a commercial ploy to avoid a more expensive and prolonged full evaluation of a drug")]},
  {h:"Moving away from race-based clinical formulas",text:"In September 2021 a joint task force of the US National Kidney Foundation and American Society of Nephrology recommended a new CKD-EPI kidney function (eGFR) equation without a race variable. In England, NICE guideline NG203 (2021) recommends the CKD-EPI creatinine equation and says not to use ethnicity as a risk factor for deciding who to test.",figure:"",year:2021,disputed:false,note:"NICE NG203 says ethnicity should not be used as a risk factor for deciding who to test for CKD. NICE also removed its 2014 recommendation to adjust the eGFR equation for adults of African-Caribbean or African family origin, finding that adding an ethnicity adjustment may not be valid or accurate.",src:[SRCQ("Chronic kidney disease: assessment and management, NG203: rationale and impact (NICE)","https://www.nice.org.uk/guidance/ng203/chapter/Rationale-and-impact","Supports the DNA and genomes page","the committee agreed to remove the 2014 recommendation on how to adjust the CKD-EPI creatinine equation"),SRCQ("NKF-ASN task force issues final report on use of race in diagnosing kidney disease (ACP Internist)","https://www.acpinternist.org/weekly/archives/2021/09/28/2.htm","Supports the DNA and genomes page","that has been refit to estimate kidney function without a race variable."),SRCQ("Chronic kidney disease: assessment and management, NG203 Recommendations (NICE)","https://www.nice.org.uk/guidance/ng203/chapter/Recommendations","Supports the DNA and genomes page","use the Chronic Kidney Disease Epidemiology Collaboration (CKD-EPI) creatinine equation"),SRCQ("NKF and ASN Release New Way to Diagnose Kidney Diseases (National Kidney Foundation, 23 Sept 2021)","https://www.kidney.org/news/nkf-and-asn-release-new-way-to-diagnose-kidney-diseases","Supports the DNA and genomes page","estimates kidney function without a race variable")]}]},
 {k:"E",h:"The genetics of the diaspora",intro:"Genetic data has added to historical records about the transatlantic trade in enslaved Africans and about the ancestry of African-descendant people in the Americas.",points:[
  {h:"Genetic legacy of the transatlantic slave trade (Micheletti et al. 2020)",text:"A 23andMe-led study (American Journal of Human Genetics, July 2020) analysed genetic data from 50,281 research participants and compared it with historical shipping records. African women contributed more than African men to present-day ancestry, although most enslaved people were men. Nigerian ancestry is over-represented in African Americans in the US, which the authors link largely to onward transport of enslaved people from the Caribbean.",figure:">50,000 participants",year:2020,disputed:false,note:"The authors link the female bias to sexual exploitation of enslaved women. The research was done by a commercial company using its customers' data.",src:[SRCQ("Exploring the History of Slavery Through Genetic African Ancestry Data (Technology Networks, 24 Jul 2020)","https://www.technologynetworks.com/genomics/news/exploring-the-history-of-slavery-through-genetic-african-ancestry-data-337839","Supports the DNA and genomes page","The female bias is particularly shocking given that the majority of enslaved individuals were male."),SRCQ("Exploring the History of Slavery Through Genetic African Ancestry Data (Technology Networks, 24 Jul 2020)","https://www.technologynetworks.com/genomics/news/exploring-the-history-of-slavery-through-genetic-african-ancestry-data-337839","Supports the DNA and genomes page","Nigerian ancestry is over-represented in African Americans in the U.S."),SRCQ("Genetic Consequences of the Transatlantic Slave Trade in the Americas (Micheletti et al., AJHG 2020; abstract)","https://europepmc.org/article/MED/32707084","Supports the DNA and genomes page","Here, we analyzed genotype array data from 50,281 research participants")]},
  {h:"Admixture in African Americans and Caribbean people",text:"African Americans typically have mixed African and European ancestry in varying proportions. Tishkoff et al. 2009 estimated averages of about 71% Niger-Kordofanian (largely West and west-central African), 13% European and 8% other African, with wide variation between individuals. Caribbean populations also show mixed African, European and other ancestries, which is why 1000 Genomes includes an African Caribbean sample from Barbados.",figure:"~71% Niger-Kordofanian, ~13% European, ~8% other African (African American average, 2009)",year:2009,disputed:false,note:"The sources cited give no admixture proportions for Caribbean or Black British populations.",src:[SRCQ("The Genetic Structure and History of Africans and African Americans (Tishkoff et al., Science 2009)","https://faculty.washington.edu/wjs18/Pop_Structure/TishkoffAfrican.pdf","Supports the DNA and genomes page","The ancestry of African Americans is predominantly from Niger-Kordofanian (~71%), European (~13%)")]},
  {h:"Limits of commercial ancestry tests",text:"Ancestry tests compare your DNA with reference databases that differ between companies and do not represent all populations equally. Results can differ between companies and show where a family originated rather than where it lived. With few African reference samples, tests cannot reliably name a particular ethnic group, town or village.",figure:"",year:"",disputed:false,note:"The final sentence is an inference from the reference-database limits; MedlinePlus does not say 'cannot name a village' in those words.",src:[SRCQ("What is genetic ancestry testing? (MedlinePlus Genetics)","https://medlineplus.gov/genetics/understanding/dtcgenetictesting/ancestrytesting/","Supports the DNA and genomes page","Populations are not represented equally in all reference databases"),SRCQ("What is genetic ancestry testing? (MedlinePlus Genetics)","https://medlineplus.gov/genetics/understanding/dtcgenetictesting/ancestrytesting/","Supports the DNA and genomes page","ancestry estimates may not be consistent from one company to another")]}]},
 {k:"F",h:"Ethics and history",intro:"Genetics has a history of being misused to justify racism. Modern African genomics aims to put African researchers and communities in charge and make sure they benefit.",points:[
  {h:"Scientific racism and what genetics actually shows",text:"Britannica describes scientific racism as false or pseudoscientific claims used to justify European colonial rule. Genetic studies in the late twentieth century refuted the existence of biologically distinct races. NHGRI describes race as a social construct, with more genetic variation within self-identified racial groups than between them.",figure:"",year:"",disputed:false,note:"The American Society of Human Genetics also published a report on the field's history in 2023. Its content is not confirmed by the sources cited.",src:[SRCQ("Scientific racism (Britannica)","https://www.britannica.com/topic/scientific-racism","Supports the DNA and genomes page","a set of falsified scientific or pseudoscientific hypotheses"),SRCQ("Race (Britannica)","https://www.britannica.com/topic/race-human","Supports the DNA and genomes page","Genetic studies in the late 20th century refuted the existence of biogenetically distinct races"),SRCQ("Race (NHGRI Talking Glossary)","https://www.genome.gov/genetics-glossary/Race","Supports the DNA and genomes page","There is more genetic variation within self-identified racial groups than between them.")]},
  {h:"Henrietta Lacks and HeLa cells",text:"In 1951 doctors at Johns Hopkins took cells from Henrietta Lacks, a Black woman being treated for cervical cancer, without her knowledge or permission. Her cells, HeLa, became widely used in research. Johns Hopkins says it should have done more to work with her family, and that it has never sold or profited from HeLa cells. In August 2023 her family reached a confidential settlement with Thermo Fisher Scientific.",figure:"",year:2023,disputed:false,note:"",src:[SRCQ("Henrietta Lacks' descendants reach a settlement over the use of her 'stolen' cells (OPB/NPR, 1 Aug 2023)","https://www.opb.org/article/2023/08/01/henrietta-lacks-descendants-reach-a-settlement-over-the-use-of-her-stolen-cells/","Supports the DNA and genomes page","The terms of the settlement agreement are confidential."),SRCQ("Henrietta Lacks' descendants reach a settlement over the use of her 'stolen' cells (OPB/NPR, 1 Aug 2023)","https://www.opb.org/article/2023/08/01/henrietta-lacks-descendants-reach-a-settlement-over-the-use-of-her-stolen-cells/","Supports the DNA and genomes page","without her knowledge or permission"),SRCQ("The Legacy of Henrietta Lacks (Johns Hopkins Medicine)","https://www.hopkinsmedicine.org/henrietta-lacks","Supports the DNA and genomes page","Johns Hopkins could have – and should have – done more to inform and work with members of Henrietta Lacks' family.")]},
  {h:"'Helicopter research' and the H3Africa ethics guidelines",text:"In 2018 the H3Africa ethics working group issued voluntary guidelines to counter 'helicopter research', where foreign scientists take samples and data from communities without lasting involvement. The guidelines say research should respect African values and benefit African citizens.",figure:"",year:2018,disputed:false,note:"",src:[SRCQ("African scientists call for more control of their continent's genomic data (Nature news via BioEd Online, 18 Apr 2018)","https://www.bioedonline.org/news/nature-news-archive/african-scientists-call-for-more-control-of-their-continente28099s-genomic-data/","Supports the DNA and genomes page","'helicopter' research, in which foreign scientists take samples and data from communities"),SRCQ("African scientists call for more control of their continent's genomic data (Nature news via BioEd Online, 18 Apr 2018)","https://www.bioedonline.org/news/nature-news-archive/african-scientists-call-for-more-control-of-their-continente28099s-genomic-data/","Supports the DNA and genomes page","The guidelines also aim to ensure that African citizens see health benefits from research.")]},
  {h:"Benefit-sharing, data sovereignty and capacity building",text:"H3Africa's biospecimen sharing policy (2021) balances protecting participants with enabling research, and aims to make African researchers competitive in genomics. The contested 54gene asset sale raised concerns, reported by TechCabal from the founder's side of the dispute, that Nigerians' genomic data could pass to the highest bidder.",figure:"",year:2021,disputed:false,note:"Details of Wellcome Sanger-funded training programmes are not confirmed by the sources cited.",src:[SRCQ("H3Africa Biospecimen Sharing, Access and Release Policy (1 March 2021)","https://h3africa.org/wp-content/uploads/2023/06/H3A-Biospecimen-Sharing-Access-and-Release-Policy_1-March-2021.pdf","Supports the DNA and genomes page","H3Africa empowers African researchers to be competitive in genomic sciences"),SRCQ("Nigerian court blocks sale of 54gene's assets, as founder claims investor wrongdoing (TechCabal)","https://techcabal.com/2025/08/01/54gene-collapse/","Supports the DNA and genomes page","risks placing the sensitive genomic data of Nigerians in the hands of the highest bidder")]},
  {h:"UK context: NHS Race and Health Observatory",text:"In June 2024 the NHS Race and Health Observatory and the University of Nottingham published a review finding that Black, Asian and minority ethnic communities are poorly represented in genetic medicine research. It examined 70 policy and guidance documents (2017–2022). Its key recommendations include making research databases representative of the population and monitoring access to genetic services by ethnicity. Historical abuses by medical institutions have reduced trust.",figure:"70 documents reviewed",year:2024,disputed:false,note:"",src:[SRCQ("New report reveals solutions to stark exclusion of ethnic minority communities in genetic research (NHS Race and Health Observatory, 5 Jun 2024)","https://nhsrho.org/news/new-report-reveals-solutions-to-stark-exclusion-of-ethnic-minority-communities-in-genetic-research/","Supports the DNA and genomes page","Black, Asian and ethnic minority communities are poorly represented in genetic medicine research"),SRCQ("New report reveals solutions to stark exclusion of ethnic minority communities in genetic research (NHS Race and Health Observatory, 5 Jun 2024)","https://nhsrho.org/news/new-report-reveals-solutions-to-stark-exclusion-of-ethnic-minority-communities-in-genetic-research/","Supports the DNA and genomes page","We found an ethnic bias in genetic datasets, with widespread under-representation of ethnic minority groups.")]}]},
 {k:"G",h:"Myths, disagreements and the limits of this evidence",intro:"The strongest case against this material, and the answers to it.",points:[
  {h:"Myth: genetics proves races exist",text:"Genetic differences between populations are real but small, gradual across geography, and mostly found within groups rather than between them. No genes mark out the conventional race categories. Ancestry is a better description than race.",figure:"Widely separated populations differ in about 6–8% of genes (Britannica)",year:"",disputed:false,note:"Self-identified race can correlate loosely with ancestry, which is why it was used as a stand-in in medicine; this is a proxy, not a biological category.",src:[SRCQ("Race (Britannica)","https://www.britannica.com/topic/race-human","Supports the DNA and genomes page","There are no genes that can identify distinct groups that accord with the conventional race categories."),SRCQ("Race (NHGRI Talking Glossary)","https://www.genome.gov/genetics-glossary/Race","Supports the DNA and genomes page","Race is a social construct used to group people.")]},
  {h:"Myth: one gene decides a complex trait",text:"Even well-known variants such as APOL1 raise risk rather than decide outcomes: most people with two APOL1 risk variants do not develop kidney disease. The Duffy-null example shows a normal variation being mistaken for illness. Complex traits also depend on environment and social factors.",figure:"",year:"",disputed:false,note:"",src:[SRCQ("Duffy-null Associated Neutrophil Count (DANC) (American Society of Hematology)","https://www.hematology.org/DANC","Supports the DNA and genomes page","often incorrectly labeled as having neutropenia")]},
  {h:"Where estimates differ",text:"Shares of African-ancestry participants in GWAS range from under 1% to about 3%, and European-ancestry shares from about 78% to 88%, depending on source and year. New-variant counts for the 2020 H3Africa study are given as 'more than 3 million' (paper) and 'about 3.4 million' (press release). Dates for the emergence of modern humans are model estimates.",figure:"",year:"",disputed:false,note:"",src:[SRCQ("Diverse Data (Genomics England)","https://www.Genomicsengland.Co.Uk/Initiatives/Diverse-Data","Supports the DNA and genomes page","Only 2% of genome-wide association studies (GWAS) participants are of African genetic ancestry."),SRCQ("Genome Data from Africa Reveal Millions of New Variants (H3Africa)","https://h3africa.org/index.php/2020/11/10/genome-data-from-africa-reveal-millions-of-new-variants/","Supports the DNA and genomes page","This work has uncovered about 3.4 million unique gene variants that had never before been described.")]}]},
];
