const GN_TIME=[{y:"1951",t:"Cells taken from Henrietta Lacks at Johns Hopkins without consent (HeLa)",src:[SRCQ("Henrietta Lacks' descendants reach a settlement over the use of her 'stolen' cells (OPB/NPR, 1 Aug 2023)","https://www.opb.org/article/2023/08/01/henrietta-lacks-descendants-reach-a-settlement-over-the-use-of-her-stolen-cells/","Supports the DNA and genomes page","The terms of the settlement agreement are confidential.")]},{y:"2002",t:"International HapMap Project begins, including Yoruba samples from Ibadan",src:[SRCQ("About the International HapMap Project (NHGRI)","https://www.genome.gov/11511175/about-the-international-hapmap-project-fact-sheet","Supports the DNA and genomes page","from the Yoruba people in Ibadan, Nigeria (30 both-parent-and-adult-child trios)")]},{y:"2005",t:"BiDil approved in the US for self-identified Black patients",src:[SRCQ("en.wikipedia.org","https://en.wikipedia.org/wiki/BiDil","Supports the DNA and genomes page","")]},{y:"2009",t:"Tishkoff et al. publish genetic structure of 121 African populations",src:[SRCQ("The Genetic Structure and History of Africans and African Americans (Tishkoff et al., Science 2009)","https://faculty.washington.edu/wjs18/Pop_Structure/TishkoffAfrican.pdf","Supports the DNA and genomes page","We studied 121 African populations, four African American populations, and 60 non-African populations.")]},{y:"2010",t:"H3Africa announced; APOL1 variants linked to kidney disease",src:[SRCQ("Our History (H3Africa)","https://h3africa.org/index.php/about/","Supports the DNA and genomes page","Following this meeting the concept of H3Africa was developed and the initiative was announced in June 2010.")]},{y:"2015",t:"African Genome Variation Project and final 1000 Genomes paper published",src:[SRCQ("The African Genome Variation Project shapes medical genetics in Africa (Gurdasani et al., Nature 2015)","https://www.nature.com/articles/nature13997","Supports the DNA and genomes page","dense genotypes from 1,481 individuals and whole-genome sequences from 320 individuals across sub-Saharan Africa")]},{y:"2016",t:"Popejoy and Fullerton: about 81% of GWAS participants of European descent; Manrai et al. HCM misclassification study",src:[SRCQ("nature.com","https://www.nature.com/articles/538161a","Supports the DNA and genomes page","")]},{y:"2017",t:"Ancient DNA: Skoglund (Cell) and Schlebusch (Science) papers",src:[SRCQ("Modern humans emerged more than 300,000 years ago, new study suggests (Uppsala University, 28 Sep 2017)","https://www.uu.se/en/press/press-releases/2017/2017-09-28-modern-humans-emerged-more-than-300000-years-ago-new-study-suggests","Supports the DNA and genomes page","The authors estimate the divergence among modern humans to have occurred between 350,000 and 260,000 years ago.")]},{y:"2018",t:"H3Africa ethics guidelines against 'helicopter research'",src:[SRCQ("African scientists call for more control of their continent's genomic data (Nature news via BioEd Online, 18 Apr 2018)","https://www.bioedonline.org/news/nature-news-archive/african-scientists-call-for-more-control-of-their-continente28099s-genomic-data/","Supports the DNA and genomes page","'helicopter' research, in which foreign scientists take samples and data from communities")]},{y:"2019",t:"Uganda Genome Resource published; 54gene founded",src:[SRCQ("Largest ever genome study of Africans could lead to new disease treatments (LSHTM)","https://www.lshtm.ac.uk/newsevents/news/2019/largest-ever-genome-study-africans-could-lead-new-disease-treatments","Supports the DNA and genomes page","using genome wide data from 6,400 Africans, including whole genome sequencing of nearly 2,000 people")]},{y:"2020",t:"Micheletti et al. on the transatlantic slave trade; Choudhury et al. 426 African genomes",src:[SRCQ("High-depth African genomes inform human migration and health (Nature, 2020)","https://www.nature.com/articles/s41586-020-2859-7","Supports the DNA and genomes page","We uncovered more than 3 million previously undescribed variants")]},{y:"2021",t:"3MAG proposal; NKF-ASN race-free eGFR recommendation; Genomics England Diverse Data",src:[SRCQ("Sequence three million genomes across Africa (Wonkam, Nature 2021)","https://www.nature.com/articles/d41586-021-00313-7","Supports the DNA and genomes page","Less than 2% of human genomes analysed so far have been those of African people")]},{y:"2022",t:"Lipson et al. ancient DNA of African foragers; Fatumo et al. diversity roadmap",src:[SRCQ("Ancient DNA and deep population structure in sub-Saharan African foragers (Lipson et al., Nature 2022)","https://www.nature.com/articles/s41586-022-04430-9","Supports the DNA and genomes page","probably reflecting Pleistocene interactions around 80–20 thousand years ago")]},{y:"2023",t:"Lacks family settlement with Thermo Fisher; All of Us releases ~250,000 genomes; 54gene shuts down",src:[SRCQ("Henrietta Lacks' descendants reach a settlement over the use of her 'stolen' cells (OPB/NPR, 1 Aug 2023)","https://www.opb.org/article/2023/08/01/henrietta-lacks-descendants-reach-a-settlement-over-the-use-of-her-stolen-cells/","Supports the DNA and genomes page","The terms of the settlement agreement are confidential.")]},{y:"2024",t:"NHS Race and Health Observatory review of ethnic inequities in genomics",src:[SRCQ("New report reveals solutions to stark exclusion of ethnic minority communities in genetic research (NHS Race and Health Observatory, 5 Jun 2024)","https://nhsrho.org/news/new-report-reveals-solutions-to-stark-exclusion-of-ethnic-minority-communities-in-genetic-research/","Supports the DNA and genomes page","Black, Asian and ethnic minority communities are poorly represented in genetic medicine research")]},{y:"2025",t:"Lagos court blocks sale of 54gene assets including biodata",src:[SRCQ("Nigerian court blocks sale of 54gene's assets, as founder claims investor wrongdoing (TechCabal)","https://techcabal.com/2025/08/01/54gene-collapse/","Supports the DNA and genomes page","Assets slated for sale included the biodata of 100,000 Nigerians priced at $3 million.")]},{y:"2026",t:"Genomics England: East African ancestry linked to ~3x more flagged variants in rare disease testing",src:[SRCQ("More diverse genomic datasets could improve equity in rare conditions diagnoses (Genomics England)","https://www.genomicsengland.co.uk/news/more-diverse-genomic-datasets-could-improve-equity-in-rare-conditions-diagnoses","Supports the DNA and genomes page","people of East African ancestry had almost three times as many genetic changes flagged for scientists to review")]}];
